
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_oblyp_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_oblyp_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.380242610422688e+00, -4.298260675253911e+00, -4.183457419546952e+00, -4.024578320968444e+00, -3.808399535280992e+00, -3.521325180150280e+00, -3.153113923024235e+00, -2.703438270596397e+00, -2.190007179529978e+00, -1.649574865458898e+00, -1.113801596390223e+00, -7.422991947522267e-01, -6.378896082158033e-01, -5.319382695044417e-01, -3.881520256626883e-01, -2.456817047007786e-01, -1.445461615803642e-01, -9.600463508932292e-02, -6.103975858038634e-02, -4.171887329538020e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


